(out/'style.css').write_text(css,encoding='utf8')
page='''<!doctype html>
<html lang="ar-EG" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مصير المبيدات في البيئة — إعادة البناء</title><link rel="stylesheet" href="style.css"></head><body><div class="shell" id="fate-v2"><nav class="top">LOGO<strong data-path-title></strong><select data-language aria-label="لغة العرض"><option value="ar">العربية المصرية</option><option value="en">English</option></select></nav><p class="notice" data-notice></p><main id="content"></main></div><script id="public-data" type="application/json">PAYLOAD</script><script src="app.js"></script></body></html>'''
page=page.replace('LOGO','<img src="'+html.escape(logo[1],quote=True)+'" alt="Masaarat">' if logo else '<span>مسارات</span>')
page=page.replace('PAYLOAD',json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</',r'<\/'))
(out/'index.html').write_text(page,encoding='utf8')
js=r'''
(()=>{
const root=document.getElementById('fate-v2'),data=JSON.parse(document.getElementById('public-data').textContent),main=document.getElementById('content');
let lang='ar',tab='reading',view='paths',drafts={},choices={},calcs={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scientific=/(\d+(?:\.\d+)?\s*(?:mg\/kg food|kg food|microgram|mg|kg|g)|C\d[A-Za-z0-9]+|mg\/kg food)/g;
const rich=s=>String(s).split(/(`[^`]+`)/).map((part,i)=>i%2?`<bdi dir="ltr"><code>${esc(part.slice(1,-1))}</code></bdi>`:esc(part).replace(scientific,'<bdi dir="ltr">$1</bdi>')).join('');
const paragraphs=xs=>xs.map(x=>'<p>'+rich(x)+'</p>').join('');
const copy={ar:{path:'مسار',paths:'المسارات — مسارات أكاديمي',open:'افتح المسار',stations:'محطات',steps:'خطوة',contents:'محطات المسار',station:'المحطة',back:'ارجع للمسار',backPaths:'ارجع للمسارات',planned:'ضمن الخطة — لسه ما اتكتبش',openStep:'افتح الخطوة',reading:'الشرح',example:'مثال محلول',quiz:'اختبر فهمك',practice:'طبّق بنفسك',faq:'أسئلة شائعة',downloads:'التحميلات',assistant:'المساعد الذكي',notice:'نسخة إعادة البناء للمراجعة: المعروض مسودة الخطوة الأولى وخطة بقية المسار. الصوت والفيديو لسه ما اتنتجوش للنسخة دي.',before:'قبل ما تبدأ',post:'بعد ما تخلص',bank:'بنك الأسئلة',write:'اكتب إجابتك ووضّح تفكيرك',check:'راجع الحساب',reset:'ابدأ الحساب من جديد',unit:'وحدة كمية المتبقي',local:'المدخلات للمعاينة الحالية فقط. الإجابات المستقلة لا تتصحح آليًا هنا، ومفيش درجة أو تقدم بيتحفظ في حساب على المنصة.',assistantNote:'مساعد المسار لسه مش مفعّل. الأسئلة الشائعة موجودة في قسمها، ومش بديل لمساعد ذكي.',worksheet:'افتح ورقة التطبيق القابلة للطباعة',source:'المصادر وحدود المحتوى',sourceNote:'الشرح مرتبط بصفحات ٣–٦ من الملف، مع إضافات وأمثلة افتراضية موثقة. مراجعة الجدول لا تعني اعتماد كل ادعاءات الأضرار فيه.'},en:{path:'Path',paths:'Paths — Masaarat Academic',open:'Open path',stations:'stations',steps:'steps',contents:'Path stations',station:'Station',back:'Back to path',backPaths:'All paths',planned:'Planned — not yet authored',openStep:'Open step',reading:'Reading',example:'Worked example',quiz:'Check understanding',practice:'Practice',faq:'FAQ',downloads:'Downloads',assistant:'AI assistant',notice:'Rebuild review: the first written step and the proposed path plan. No new-edition audio or video has been produced.',before:'Before you start',post:'After the lesson',bank:'Question bank',write:'Write your answer and reasoning',check:'Check calculation',reset:'Reset calculation',unit:'Residue amount unit',local:'Inputs apply only to this preview session. Independent answers are not automatically graded here, and no platform account progress is saved.',assistantNote:'The path assistant is not active. FAQ content is available separately; it is not an AI assistant.',worksheet:'Open printable practice worksheet',source:'Sources and scope',sourceNote:'Core explanation maps to source pages 3–6, with documented authored hypothetical examples. Critical table reading does not validate all attributed effects.'}};
function number(value){let s=String(value??'').trim().replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٫,]/g,'.');if(!s)return null;if(!/^[+-]?(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(s))return NaN;const n=Number(s);return Number.isFinite(n)?n:NaN}
function qs(items,group){return items.map(q=>{const v=q[lang],key=q.id+'-'+lang+'-'+group;return `<fieldset class="question"><legend>${rich(v.question)}</legend>${v.options?v.options.map((o,i)=>`<label class="option"><input type="radio" name="${key}" data-choice="${key}" value="${i}" ${choices[key]===String(i)?'checked':''}><span>${rich(o)}</span></label>`).join(''):`<textarea rows="4" maxlength="5000" data-draft="${key}" aria-label="${esc(v.question)}" placeholder="${copy[lang].write}">${esc(drafts[key]||'')}</textarea>`}</fieldset>`}).join('')}
function render(){const t=copy[lang],v=data.lesson[lang];root.dir=lang==='ar'?'rtl':'ltr';document.documentElement.dir=root.dir;document.documentElement.lang=lang==='ar'?'ar-EG':'en';root.querySelector('[data-language]').value=lang;root.querySelector('[data-path-title]').textContent=data.map.path[lang];root.querySelector('[data-notice]').textContent=t.notice;
if(view==='paths'){main.innerHTML=`<div class="catalogue"><header class="hero"><h1>${t.paths}</h1></header><a class="path-card" href="#path"><div><h2>${t.path} ${data.map.path[lang]}</h2><p>11 ${t.steps} · 5 ${t.stations}</p></div><span>${t.open}</span></a></div>`;return}
if(view==='path'){main.innerHTML=`<div class="catalogue"><header class="hero"><h1>${t.contents}</h1><p>${data.map.path[lang]}</p></header><a class="action" href="#paths">${t.backPaths}</a>`+data.map.stations.map(s=>`<section class="station"><h2>${t.station} — ${s.title[lang]}</h2>${s.steps.map(id=>{const step=data.map.steps.find(x=>x.id===id);return id===data.lesson.id?`<a class="step-row" href="#step/FATE2-S01"><span>${step.title[lang]}</span><b>${t.openStep}</b></a>`:`<div class="step-row"><span>${step.title[lang]}</span><small>${t.planned}</small></div>`}).join('')}</section>`).join('')+'</div>';return}
const keys=['reading','example','quiz','practice','faq','downloads','assistant'];
main.innerHTML=`<a class="action" href="#path">${t.back}</a><header class="hero"><small>${lang==='ar'?'مسارات أكاديمي':'Masaarat Academic'}</small><h1>${v.title}</h1><p>${v.intro}</p></header><div class="layout"><aside class="sidebar"><nav class="tabs" role="tablist" aria-label="${lang==='ar'?'أقسام الخطوة':'Step sections'}">${keys.map(k=>`<button type="button" role="tab" id="tab-${k}" aria-selected="${tab===k}" aria-controls="panel" data-tab="${k}">${t[k]}</button>`).join('')}</nav></aside><section class="panel" id="panel" role="tabpanel" aria-labelledby="tab-${tab}"></section></div>`;
const panel=document.getElementById('panel');
if(tab==='reading')panel.innerHTML='<ul>'+v.outcomes.map(x=>'<li>'+rich(x)+'</li>').join('')+'</ul>'+`<details><summary>${t.before}</summary><div>${qs(data.questions.items.filter(x=>x.stage==='diagnostic'),'before')}</div></details>`+v.sections.map(s=>`<article class="reading-section"><h2>${s.title}</h2>${paragraphs(s.paragraphs)}</article>`).join('')+`<section class="reading-section"><h2>${lang==='ar'?'الخلاصة':'Take-away'}</h2><ul>${v.summary.map(x=>'<li>'+rich(x)+'</li>').join('')}</ul><p>${v.next}</p></section><details><summary>${t.source}</summary><div><p>${t.sourceNote}</p><a href="../../sources/Fate-Pesticides-Dr%20E.%20Swelam.pdf">${lang==='ar'?'الملف المصدر':'Source handout'}</a><p><a href="https://codex.fao.org/codex-texts/codex-online-databases/pesticides-residues/glossary" target="_blank" rel="noopener">Codex</a> · <a href="https://www.epa.gov/pesticide-science-and-assessing-pesticide-risks/assessing-human-health-risk-pesticides" target="_blank" rel="noopener">EPA</a></p></div></details>`;
if(tab==='example')panel.innerHTML='<h2>'+v.example.title+'</h2><p>'+rich(v.example.scenario)+'</p>'+v.example.steps.map((s,i)=>`<article class="reading-section"><h3>${i+1}. ${s.text}</h3><p class="equation"><bdi dir="ltr">${esc(s.equation)}</bdi></p></article>`).join('')+paragraphs([v.example.conclusion,v.example.commonError]);
if(tab==='quiz')panel.innerHTML=`<p class="note">${t.local}</p>`+qs(data.questions.items.filter(x=>x.stage==='post'),'post');
if(tab==='practice'){const c=calcs[lang]||{};panel.innerHTML=`<h2>${v.guided.title}</h2><p>${rich(v.guided.scenario)}</p><div class="calc-fields"><label class="answer-field">${v.guided.massLabel}<input inputmode="decimal" type="text" data-calc="mass" value="${esc(c.mass||'')}" aria-label="${v.guided.massLabel}"></label><label class="answer-field">${v.guided.amountLabel}<input inputmode="decimal" type="text" data-calc="amount" value="${esc(c.amount||'')}" aria-label="${v.guided.amountLabel}"></label></div><label class="answer-field">${t.unit}<select data-unit aria-label="${t.unit}"><option value="mg" ${c.unit!=='g'?'selected':''}>mg</option><option value="g" ${c.unit==='g'?'selected':''}>g</option></select></label><button class="primary" data-check type="button">${t.check}</button> <button data-reset type="button">${t.reset}</button><p class="feedback" role="status" aria-live="polite">${c.message?rich(v.guided.feedback[c.message]):''}</p><section class="reading-section"><h2>${lang==='ar'?'طبّق الاستدلال':'Apply the reasoning'}</h2>${v.practice.map((q,i)=>`<label class="answer-field">${rich(q)}<textarea rows="4" data-draft="practice-${lang}-${i}">${esc(drafts['practice-'+lang+'-'+i]||'')}</textarea></label>`).join('')}</section><p class="note">${t.local}</p>`}
if(tab==='faq')panel.innerHTML=v.faq.map(f=>`<details><summary>${f.question}</summary><div><p>${rich(f.answer)}</p></div></details>`).join('');
if(tab==='downloads')panel.innerHTML=`<a class="action" href="worksheet-${lang}.html" target="_blank" rel="noopener">${t.worksheet}</a><details><summary>${t.bank}</summary><div>${qs(data.questions.items,'bank')}</div></details><p class="note">${t.local}</p>`;
if(tab==='assistant')panel.innerHTML='<p>'+t.assistantNote+'</p>';
}
root.addEventListener('input',e=>{if(e.target.dataset.draft)drafts[e.target.dataset.draft]=e.target.value;if(e.target.dataset.calc){calcs[lang]??={};calcs[lang][e.target.dataset.calc]=e.target.value;delete calcs[lang].message;const f=root.querySelector('.feedback');if(f)f.textContent=''}});
root.addEventListener('change',e=>{if(e.target.matches('[data-language]')){lang=e.target.value;render()}if(e.target.dataset.choice)choices[e.target.dataset.choice]=e.target.value;if(e.target.matches('[data-unit]')){calcs[lang]??={};calcs[lang].unit=e.target.value;delete calcs[lang].message;const f=root.querySelector('.feedback');if(f)f.textContent=''}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){tab=b.dataset.tab;render();return}if(e.target.closest('[data-reset]')){calcs[lang]={};render();return}if(e.target.closest('[data-check]')){const c=calcs[lang]??={},mass=number(c.mass),amount=number(c.amount);c.message=mass===null||amount===null?'empty':!Number.isFinite(mass)||!Number.isFinite(amount)?'invalid':Math.abs(mass-.3)>1e-10?'mass':c.unit==='g'?'unit':Math.abs(amount-.027)>1e-10?'amount':'correct';render()}});
function route(){view=location.hash==='#path'?'path':location.hash==='#step/FATE2-S01'?'step':'paths';tab='reading';render()}window.addEventListener('hashchange',route);route();
})();
'''
(out/'app.js').write_text(js,encoding='utf8')

def plain(v):return html.escape(v).replace('`','')
for lang in ['ar','en']:
 v=lesson[lang]
 content='<h1>'+v['title']+'</h1><p>'+v['example']['scenario']+'</p><p>'+('اكتب التحويل والحساب والافتراضات وحدود الاستنتاج.' if lang=='ar' else 'Show conversion, units, assumptions and limits of inference.')+'</p><div class="lines"></div>'
 for q in questions['items']:
  if q['stage']!='post':continue
  content+='<section><h2>'+plain(q[lang]['question'])+'</h2>'
  if 'options' in q[lang]:content+='<ul>'+''.join('<li><bdi>'+plain(o)+'</bdi></li>' for o in q[lang]['options'])+'</ul>'
  content+='<div class="lines"></div></section>'
 content='<!doctype html><html lang="'+('ar-EG' if lang=='ar' else 'en')+'" dir="'+('rtl' if lang=='ar' else 'ltr')+'"><meta charset="utf-8"><title>'+v['title']+'</title><style>'+fonts+'body{font-family:MasaaratTajawal,Arial,sans-serif;max-width:800px;margin:24px auto;line-height:1.9;padding:16px}h1{font-size:24px}h2{font-size:18px}section{break-inside:avoid;margin-top:24px}.lines{height:95px;background:repeating-linear-gradient(transparent 0,transparent 30px,#bbb 31px,transparent 32px)}@page{size:A4;margin:18mm}@media print{button{display:none}body{margin:0;padding:0}}bdi{unicode-bidi:isolate}</style><button onclick="window.print()">'+('طباعة' if lang=='ar' else 'Print')+'</button>'+content+'</html>'
 (out/f'worksheet-{lang}.html').write_text(content,encoding='utf8')
receipt={'status':'written_pilot_preview_created','publicInputs':['lessons/FATE2-S01/lesson.public.json','lessons/FATE2-S01/assessment.public.json','blueprint/map.en.json'],
 'publicFiles':{p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in out.iterdir() if p.is_file()},
 'privateInputsRead':False,'mediaProduction':False,'platformWrites':False,'browserLayoutVerified':False,'printPaginationVerified':False,
 'guidedCase':'GUIDED-R-300; formative calculation/feedback only; no independent post keys embedded.'}
(R/'preview-receipt.en.json').write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf8')
